export interface LogReturnOptions {
    /**
     * How many bars back the value is compared with. Default 1, from 1 to 500.
     */
    period?: number;
    /**
     * Compare with n bars ago, or with the first bar loaded (which moves when more history loads).
     * Default 'period'.
     */
    mode?: 'period' | 'cumulative';
    /**
     * Which value of each bar the indicator reads. Default 'close'.
     */
    source?: 'close' | 'open' | 'high' | 'low' | 'hl2' | 'hlc3' | 'ohlc4';
}

/**
 * Log Return. The natural log of the value over the value n bars ago, or over the first bar on the
 * chart: about the percent change as a fraction for small moves, and log returns add up across
 * bars.
 *
 * Ported from pandas-ta-classic 0.8.32 (pandas_ta_classic/performance/log_return.py); verified
 * against pandas-ta-classic 0.8.32 on the fixture log_return.json.
 *
 * @param input Bars, oldest first, or columns of open, high, low, close and volume.
 * @param options period, mode, source: see LogReturnOptions.
 * @returns value: The log of now over then; none where either value is 0 or below.
 */
export function logReturn(input: OhlcvInput, options: LogReturnOptions = {}): { value: Series } {
    return calculate('log_return', input, options) as { value: Series };
}

/**
 * The settings of drawdown. Every one is optional.
 */
export interface DrawdownOptions {
    /**
     * Which value of each bar the indicator reads. Default 'close'.
     */
    source?: 'close' | 'open' | 'high' | 'low' | 'hl2' | 'hlc3' | 'ohlc4';
}

/**
 * Drawdown from High. How far the value sits below the highest it has been on the chart so far, in
 * points, as a fraction of that high, and in log terms: 0 at a new high, growing as price falls
 * away from it.
 *
 * Ported from pandas-ta-classic 0.8.32 (pandas_ta_classic/performance/drawdown.py); verified
 * against pandas-ta-classic 0.8.32 on the fixture drawdown.json.
 *
 * @param input Bars, oldest first, or columns of open, high, low, close and volume.
 * @param options source: see DrawdownOptions.
 * @returns value: The highest value so far minus this one, in price units; 0 at a new high.
 * fraction: The drawdown as a fraction of the high: 0.05 is 5% below it. log: The log of the high
 * over this value; none where either is 0 or below.
 */
export function drawdown(input: OhlcvInput, options: DrawdownOptions = {}): { value: Series; fraction: Series; log: Series } {
    return calculate('drawdown', input, options) as { value: Series; fraction: Series; log: Series };
}

/**
 * The settings of linregIntercept. Every one is optional.
 */
export interface LinregInterceptOptions {
    /**
     * The bars the line is fitted through. Default 14, from 2 to 500.
     */
    period?: number;
    /**
     * Which value of each bar the indicator reads. Default 'close'.
     */
    source?: 'close' | 'open' | 'high' | 'low' | 'hl2' | 'hlc3' | 'ohlc4';
}

/**
 * Linear Regression Intercept. Where the best-fit straight line through the last n bars starts:
 * its value at the oldest bar of the window. It trails price by about the window, the other end of
 * the line from the regression value.
 *
 * Ported from TA-Lib 0.8.1 (ta_LINEARREG_INTERCEPT.c); verified against TA-Lib 0.8.1 on the
 * fixture linreg_intercept.json.
 *
 * @param input Bars, oldest first, or columns of open, high, low, close and volume.
 * @param options period, source: see LinregInterceptOptions.
 * @returns value: The fitted line's value at the window's oldest bar, in price units.
 */
export function linregIntercept(input: OhlcvInput, options: LinregInterceptOptions = {}): { value: Series } {
    return calculate('linreg_intercept', input, options) as { value: Series };
}

